INSERT INTO `playbooks` VALUES (1,'Ransomware Response Playbook','Ransomware','Step-by-step guide to contain and recover from ransomware.'),(2,'Phishing Incident Playbook','Phishing Attack','Actions to identify and remediate phishing attacks.'),(3,'Data Breach Response Playbook','Data Breach','Procedures for containing and reporting a data breach.'),(4,'DDoS Mitigation Playbook','DDoS Attack','Mitigation strategies for distributed denial of service.'),(5,'Insider Threat Response Playbook','Insider Threat','Steps to investigate and contain insider threat incidents.'),(6,'Account Compromise Playbook','Account Compromise','Procedures to recover compromised user accounts.'),(7,'Malware Outbreak Playbook','Malware Outbreak','Containment and eradication steps for malware outbreaks.'),(8,'BEC Fraud Response Playbook','BEC Fraud','Actions to take when Business Email Compromise is detected.'),(9,'Supply Chain Attack Playbook','Supply Chain Attack','Steps for investigating supply chain attacks.'),(10,'Zero Day Response Playbook','Zero Day Exploitation','Emergency procedures for zero day exploitation.'),(11,'Cryptojacking Response Playbook','Cryptojacking','Detection and removal of unauthorized cryptocurrency miners.'),(12,'Social Engineering Playbook','Social Engineering','Awareness and response to social engineering attacks.'),(13,'Credential Theft Playbook','Credential Theft','Steps to identify stolen credentials and prevent misuse.'),(14,'Network Intrusion Playbook','Network Intrusion','Procedures for detecting and isolating network intrusions.'),(15,'Mobile Device Compromise Playbook','Mobile Threat','Response procedures for compromised mobile devices.'),(16,'Security Playbook 001','Incident Type 1','Generic response playbook 1 for security incidents.'),(17,'Security Playbook 002','Incident Type 2','Generic response playbook 2 for security incidents.'),(18,'Security Playbook 003','Incident Type 3','Generic response playbook 3 for security incidents.'),(19,'Security Playbo